// Keyword Queue -- mirrors the production SQLite `keyword_queue` table.
// In production a query picks one pending keyword per run using a KD-rotation
// rule (favor one high-difficulty keyword per two low-difficulty ones per
// category). Here we hold three sample rows and apply the same pick.
const queue = [
  { keyword: "how large language models generate text", difficulty: 41, kd_type: "high_kd", category: "AI & Machine Learning", status: "pending" },
  { keyword: "best free ai writing tools 2026",          difficulty: 28, kd_type: "low_kd",  category: "AI & Machine Learning", status: "pending" },
  { keyword: "what is retrieval augmented generation",   difficulty: 33, kd_type: "low_kd",  category: "AI & Machine Learning", status: "pending" },
];

const pending = queue.filter(k => k.status === "pending");
const picked  = pending.find(k => k.kd_type === "high_kd") || pending[0];

return [{
  json: {
    keyword:     picked.keyword,
    difficulty:  picked.difficulty,
    kd_type:     picked.kd_type,
    category:    picked.category,
    queue_depth: pending.length,
    run_started: new Date().toISOString(),
  },
}];

