// Normalize LLM Output -- unwrap whichever provider answered into one contract.
// Groq (OpenAI-compatible) and Gemini return different shapes; downstream nodes
// should not care which one ran. Pull the keyword from the queue node so the
// article facts survive even when an LLM node failed and passed only an error.
const kw  = $('Keyword Queue').first().json;
const inp = $input.item.json;

let title = null, article = null, meta = null, provider = null;

// Groq / OpenAI-compatible success shape
if (inp.choices && inp.choices[0] && inp.choices[0].message) {
  provider = "groq:llama-3.3-70b-versatile";
  try {
    const p = JSON.parse(inp.choices[0].message.content);
    title = p.title; article = p.article; meta = p.meta_description;
  } catch (e) { /* fall through */ }
}

// Gemini success shape
if (!article && inp.candidates && inp.candidates[0]) {
  provider = "gemini:gemini-2.5-flash";
  try {
    const t = inp.candidates[0].content.parts[0].text;
    const p = JSON.parse(t);
    title = p.title; article = p.article; meta = p.meta_description;
  } catch (e) { /* fall through */ }
}

// Demo safety net: no live key, both providers returned no usable content.
// Emit a labeled deterministic article so the pipeline runs end to end.
let demoMode = false;
if (!article) {
  demoMode = true;
  provider = provider || "demo-fallback (no API key set)";
  const k = kw.keyword;
  const T = k.charAt(0).toUpperCase() + k.slice(1);
  title = T + ": A Practical 2026 Guide";
  article =
    "<p><strong>" + T + "</strong> is a topic every " + kw.category + " reader runs into. " +
    "This sample article stands in for live model output so the pipeline runs without an API key.</p>" +
    "<h2>Why " + T + " Matters</h2><p>Placeholder body generated deterministically from the keyword row. " +
    "With a Groq or Gemini key wired in, this section carries real model output using the same JSON contract.</p>" +
    "<h2>How It Works</h2><p>The queue picked \"" + k + "\" (difficulty " + kw.difficulty + ", " + kw.kd_type + "). " +
    "The failover chain tried Groq first, then Gemini. Both returned nothing in demo mode, so this stand-in was used.</p>" +
    "<h2>Conclusion</h2><p>Swap in a real key to see genuine articles flow through the same SEO, publish, and logging stages.</p>";
  meta = T + ": a practical 2026 guide covering " + k + " for " + kw.category + " readers.";
}

return { json: {
  keyword:          kw.keyword,
  category:         kw.category,
  difficulty:       kw.difficulty,
  kd_type:          kw.kd_type,
  provider_used:    provider,
  demo_mode:        demoMode,
  title:            title,
  article:          article,
  meta_description: meta,
} };

// SEO Package -- slug, meta trim to 155, focus keyword, word count, Article schema.
const d = $input.item.json;

const slug = (d.title || d.keyword).toLowerCase()
  .replace(/[^a-z0-9\s-]/g, "")
  .trim().replace(/\s+/g, "-").slice(0, 60).replace(/-+$/, "");

let meta = (d.meta_description || "").trim();
if (meta.length > 155) meta = meta.slice(0, 152).replace(/\s+\S*$/, "") + "...";

// focus keyword: drop stopwords, keep at most 4 words (mirrors _derive_focus_keyword)
const STOP = new Set(["how","what","why","when","where","who","which","is","are","the","a","an","to","in","on","of","for","and","best"]);
const focus = d.keyword.split(/\s+/).filter(w => !STOP.has(w.toLowerCase())).slice(0, 4).join(" ") || d.keyword;

const words = (d.article || "").replace(/<[^>]+>/g, " ").split(/\s+/).filter(Boolean).length;

return { json: Object.assign({}, d, {
  slug: slug,
  meta_description: meta,
  focus_keyword: focus,
  word_count: words,
  schema: {
    "@context": "https://schema.org",
    "@type": "Article",
    "headline": d.title,
    "description": meta,
    "keywords": focus,
  },
}) };

