// Run Log -- one outcome summary per run (mirrors production post_log + agent_runs).
// Pull article facts from the SEO node; the publish response replaced $json.
const seo = $('SEO Package').first().json;
const pub = $input.item.json;                 // httpbin echo, or error if unreachable
const published = !!(pub && pub.json);        // httpbin returns { json: <our payload> }

const summary = {
  status:                published ? "published" : "publish_failed",
  timestamp:             new Date().toISOString(),
  keyword:               seo.keyword,
  title:                 seo.title,
  slug:                  seo.slug,
  focus_keyword:         seo.focus_keyword,
  word_count:            seo.word_count,
  meta_description:      seo.meta_description,
  provider_used:         seo.provider_used,
  demo_mode:             seo.demo_mode,
  mock_publish_endpoint: "https://httpbin.org/post",
  mock_echo_url:         (pub && pub.url) ? pub.url : null,
};
console.log("[RUN LOG] " + JSON.stringify(summary, null, 2));
return { json: summary };
